import{_ as e,o as a,c as t,a2 as o}from"./chunks/framework.DBSoX6Zw.js";const g=JSON.parse('{"title":"Import / Export","description":"","frontmatter":{},"headers":[],"relativePath":"operations/import-export.md","filePath":"operations/import-export.md"}'),i={name:"operations/import-export.md"};function n(p,s,r,l,d,c){return a(),t("div",null,[...s[0]||(s[0]=[o(`<h1 id="import-export" tabindex="-1">Import / Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import / Export&quot;">​</a></h1><p>Plik can export and import all metadata (users, tokens, uploads, files, settings) using the <code>plikd</code> CLI. This is useful for <strong>backend migrations</strong> (e.g. SQLite → PostgreSQL), <strong>backups</strong>, and <strong>disaster recovery</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Import/export handles <strong>metadata only</strong> — file data stored in the data backend (filesystem, S3, etc.) is not included. You must separately back up or migrate the data backend contents.</p></div><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Dump all metadata to a file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plikd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/export.bin</span></span></code></pre></div><p>Sample output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exporting metadata from sqlite3 to /path/to/export.bin</span></span>
<span class="line"><span>exported 3 users</span></span>
<span class="line"><span>exported 5 tokens</span></span>
<span class="line"><span>exported 142 uploads</span></span>
<span class="line"><span>exported 287 files</span></span>
<span class="line"><span>exported 1 settings</span></span></code></pre></div><p>The export includes soft-deleted uploads to preserve foreign key integrity. CLI auth sessions are <strong>not exported</strong> — they are ephemeral and have no value outside the running server.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Load metadata from a previously exported file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plikd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/export.bin</span></span></code></pre></div><p>Sample output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Importing metadata from /path/to/export.bin to postgres</span></span>
<span class="line"><span>imported 3 out of 3 uploads</span></span>
<span class="line"><span>imported 287 out of 287 files</span></span>
<span class="line"><span>imported 3 out of 3 users</span></span>
<span class="line"><span>imported 5 out of 5 tokens</span></span>
<span class="line"><span>imported 1 out of 1 settings</span></span></code></pre></div><h3 id="ignore-errors" tabindex="-1"><code>--ignore-errors</code> <a class="header-anchor" href="#ignore-errors" aria-label="Permalink to &quot;\`--ignore-errors\`&quot;">​</a></h3><p>By default, import stops on the first error (e.g. a duplicate key). Use <code>--ignore-errors</code> to skip problematic records and continue:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plikd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-errors</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/export.bin</span></span></code></pre></div><p>Failed records are logged to stdout with details.</p><h2 id="file-format" tabindex="-1">File Format <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;File Format&quot;">​</a></h2><p>The export file uses Go&#39;s <a href="https://pkg.go.dev/encoding/gob" target="_blank" rel="noreferrer">gob</a> encoding compressed with <a href="https://github.com/golang/snappy" target="_blank" rel="noreferrer">Snappy</a>. This format is:</p><ul><li><strong>Architecture-independent</strong> — portable across <code>amd64</code>, <code>arm64</code>, etc.</li><li><strong>Compact</strong> — binary encoding + compression keeps files small</li><li><strong>Streaming</strong> — objects are written sequentially, so memory usage stays constant regardless of database size</li><li><strong>Go-specific</strong> — the file cannot be read by non-Go tools</li></ul>`,21)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
